mapper.select:
SELECT t.userEmail AS userEmail, t.category AS category, SUM(t.score) AS score FROM ( SELECT pr.useremail AS userEmail, p.category AS category, 3 + CASE WHEN pr.rating >= 4 THEN 2 ELSE 0 END AS score FROM place_review pr INNER JOIN place p ON p.place_id = pr.place_id WHERE pr.useremail = #{userEmail}
UNION ALL
SELECT pl.useremail AS userEmail, p.category AS category, 2 AS score FROM place_like pl INNER JOIN place p ON p.place_id = pl.place_id WHERE pl.useremail = #{userEmail} ) t GROUP BY t.userEmail, t.category ORDER BY score DESC LIMIT 3
